const input = $json.body || $json;
const candidate = input.candidate_profile || input.candidate || {};
const jobs = input.jobs || [];

if (!candidate.candidate_id || !Array.isArray(jobs) || jobs.length === 0) {
  throw new Error('Candidate Profile or Jobs array is missing/empty.');
}

return [{ json: { candidate, jobs } }];

const data = $node["02 - Parse Input Features"].json;
const candidate = data.candidate;
const jobs = data.jobs;

const synonyms = {
  'js': ['javascript', 'js', 'typescript', 'ts'],
  'javascript': ['javascript', 'js', 'typescript', 'ts'],
  'typescript': ['javascript', 'js', 'typescript', 'ts'],
  'ts': ['javascript', 'js', 'typescript', 'ts'],
  'postgres': ['postgresql', 'postgres', 'sql'],
  'postgresql': ['postgresql', 'postgres', 'sql'],
  'sql': ['sql', 'postgresql', 'postgres', 'sqlite', 'mysql']
};

const candSkills = [...(candidate.technical_skills || []), ...(candidate.programming_languages || []), ...(candidate.frameworks || []), ...(candidate.tools || [])].map(s => s.toLowerCase().trim());

function checkSkillMatch(skill) {
  const sLower = skill.toLowerCase().trim();
  if (candSkills.includes(sLower)) return true;
  for (const key in synonyms) {
    if (synonyms[key].includes(sLower) && synonyms[key].some(syn => candSkills.includes(syn))) {
      return true;
    }
  }
  return false;
}

const results = jobs.map(job => {
  const matched = [];
  const missing = [];
  (job.required_skills || []).forEach(s => {
    if (checkSkillMatch(s)) matched.push(s);
    else missing.push(s);
  });

  const score = job.required_skills.length > 0 ? (matched.length / job.required_skills.length) * 100 : 100;

  return {
    job_id: job.job_id,
    job: job,
    matched_skills: matched,
    missing_skills: missing,
    keyword_score: score
  };
});

return [{ json: { candidate, results } }];

const data = $node["03 - Calculate Skill Match"].json;
const candidate = data.candidate;
const results = data.results;

const candTitles = [...(candidate.preferred_roles || []), ...(candidate.job_titles || [])].map(t => t.toLowerCase().trim());
const candKeywords = (candidate.keywords || []).map(k => k.toLowerCase().trim());

const updatedResults = results.map(item => {
  const job = item.job;

  // Title similarity
  let titleSim = 0.0;
  const jobTitleLower = (job.job_title || '').toLowerCase();
  const isTitleMatch = candTitles.some(title => jobTitleLower.includes(title));
  if (isTitleMatch) titleSim = 1.0;

  // Keyword overlap
  let kwSim = 0.0;
  const jobDescLower = (job.description || '').toLowerCase();
  if (candKeywords.length > 0) {
    const matchedKw = candKeywords.filter(kw => jobDescLower.includes(kw));
    kwSim = matchedKw.length / candKeywords.length;
  } else {
    kwSim = 1.0;
  }

  const semanticSimilarity = (titleSim * 0.5) + (kwSim * 0.5);
  const score = semanticSimilarity * 100;

  return {
    ...item,
    semantic_similarity: semanticSimilarity,
    semantic_score: score
  };
});

return [{ json: { candidate, results: updatedResults } }];

const data = $node["04 - Calculate Semantic Match"].json;
const candidate = data.candidate;
const results = data.results;

const candExp = candidate.experience_years || 0;

const updatedResults = results.map(item => {
  const job = item.job;
  const reqExp = job.required_experience_years || 0;
  const satisfied = candExp >= reqExp;

  const score = reqExp > 0 ? Math.min((candExp / reqExp) * 100, 100) : 100;

  return {
    ...item,
    experience_match: {
      candidate_years: candExp,
      required_years: reqExp,
      satisfied: satisfied
    },
    experience_score: score
  };
});

return [{ json: { candidate, results: updatedResults } }];

const data = $node["05 - Calculate Experience Match"].json;
const results = data.results;

const finalJobs = results.map(item => {
  const job = item.job;

  const wKeyword = 0.3;
  const wSemantic = 0.4;
  const wExperience = 0.3;

  const finalScore = parseFloat(((item.keyword_score * wKeyword) + (item.semantic_score * wSemantic) + (item.experience_score * wExperience)).toFixed(1));

  let decision = 'SKIP';
  if (finalScore >= 85) decision = 'APPLY';
  else if (finalScore >= 60) decision = 'REVIEW';

  const explanation = `Matched ${item.matched_skills.length} skills (missing ${item.missing_skills.length}). Experience req of ${item.experience_match.required_years} years is ${item.experience_match.satisfied ? 'satisfied' : 'not satisfied'} with candidate's ${item.experience_match.candidate_years} years. Role alignment scored ${Math.round(item.semantic_score)}%.`;

  return {
    schema_version: job.schema_version || "1.0",
    job_id: job.job_id,
    job_title: job.job_title,
    company: job.company,
    location: job.location,
    source: job.source,
    description: job.description,
    application_url: job.application_url,
    required_skills: job.required_skills,
    retrieved_at: job.retrieved_at,
    employment_type: job.employment_type || "Full-time",
    seniority_level: job.seniority_level || "Mid",
    salary: job.salary || null,
    education_requirement: job.education_requirement || null,
    required_experience_years: job.required_experience_years || 0,
    preferred_skills: job.preferred_skills || [],
    technologies: job.technologies || [],
    match_score: finalScore,
    score_breakdown: {
      keyword_score: parseFloat(item.keyword_score.toFixed(1)),
      semantic_score: parseFloat(item.semantic_score.toFixed(1)),
      experience_score: parseFloat(item.experience_score.toFixed(1)),
      weights: {
        keyword: wKeyword,
        semantic: wSemantic,
        experience: wExperience
      }
    },
    matched_skills: item.matched_skills,
    missing_skills: item.missing_skills,
    experience_match: item.experience_match,
    semantic_similarity: parseFloat(item.semantic_similarity.toFixed(2)),
    decision: decision,
    explanation: explanation,
    method: "hybrid",
    ranked_at: new Date().toISOString()
  };
});

return [{ json: { ranked_jobs: finalJobs } }];

const jobs = $node["06 - Generate Decisions & Explanations"].json.ranked_jobs;

jobs.sort((a, b) => {
  if (b.match_score !== a.match_score) {
    return b.match_score - a.match_score;
  }
  // Deterministic tie-breaker
  return a.job_id.localeCompare(b.job_id);
});

return [{ json: { ranked_jobs: jobs } }];

const check = $node["08 - Validate Contract"].json;
if (!check.valid) {
  throw new Error('Contract schema violation on ranked_jobs: ' + JSON.stringify(check.errors));
}
return [{ json: { ranked_jobs: $node["07 - Sort & Rank Jobs"].json.ranked_jobs } }];
